  ('00000000-0000-4000-a000-000000000009'::uuid, 'anna@demo.roompair.example', 'Anna'),
  ('00000000-0000-4000-a000-000000000010'::uuid, 'lucas@demo.roompair.example', 'Lucas'),
  ('00000000-0000-4000-a000-000000000011'::uuid, 'laura@demo.roompair.example', 'Laura'),
  ('00000000-0000-4000-a000-000000000012'::uuid, 'daniel@demo.roompair.example', 'Daniel'),
  ('00000000-0000-4000-a000-000000000013'::uuid, 'amira@demo.roompair.example', 'Amira'),
  ('00000000-0000-4000-a000-000000000014'::uuid, 'marta@demo.roompair.example', 'Marta'),
  ('00000000-0000-4000-a000-000000000015'::uuid, 'tomas@demo.roompair.example', 'Tomas'),
  ('00000000-0000-4000-a000-000000000016'::uuid, 'kenji@demo.roompair.example', 'Kenji'),
  ('00000000-0000-4000-a000-000000000017'::uuid, 'elina@demo.roompair.example', 'Elīna'),
  ('00000000-0000-4000-a000-000000000018'::uuid, 'mateo@demo.roompair.example', 'Mateo'),
  ('00000000-0000-4000-a000-000000000019'::uuid, 'priya@demo.roompair.example', 'Priya'),
  ('00000000-0000-4000-a000-000000000020'::uuid, 'jonas@demo.roompair.example', 'Jonas'),
  ('00000000-0000-4000-a000-000000000021'::uuid, 'aleksandra@demo.roompair.example', 'Aleksandra'),
  ('00000000-0000-4000-a000-000000000022'::uuid, 'chidi@demo.roompair.example', 'Chidi')
) as demo (id, email, name)
on conflict (id) do nothing;

insert into auth.identities (
  id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at
)
select
  gen_random_uuid(), u.id, u.id::text, 'email',
  jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true),
  now(), now(), now()
from auth.users u
where u.email like '%@demo.roompair.example'
  and not exists (
    select 1 from auth.identities i where i.user_id = u.id and i.provider = 'email'
  );

-- The sign-up trigger has already created a bare profile for each account.
update public.profiles p set
  name = d.name, age = d.age, status = d.status, occupation = d.occupation,
  university = d.university, languages = d.languages, gender = d.gender,
  city = d.city, neighborhood = d.neighborhood, bio = d.bio,
  photo_url = d.photo_url, photos = d.photos, tags = d.tags, prompts = d.prompts,
  intent = d.intent, budget_min = d.budget_min, budget_max = d.budget_max,
  move_date = d.move_date, stay_months = d.stay_months,
  cleanliness = d.cleanliness, social = d.social, sleep = d.sleep,
  smokes = d.smokes, has_pets = d.has_pets, guests = d.guests,
  home_days = d.home_days, noise = d.noise, sharing = d.sharing,
  verified = d.verified, active = d.active,
  demo_likes_newcomers = d.demo_likes_newcomers, is_demo = true, onboarded = true
